import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec(torch::Tensor A, torch::Tensor B);
"""

matvec_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// C = A * B with A: (M, K) row-major, B: (K, 1)
// One thread block per output row; threads cooperatively reduce along K
// using CuTe tensors with vectorized (float4) global loads.
template <int Threads, int Vec>
__global__ __launch_bounds__(Threads)
void matvec_cute_kernel(const float* __restrict__ A,
                        const float* __restrict__ B,
                        float* __restrict__ C,
                        int M, int K)
{
  const int m   = blockIdx.x;
  const int tid = threadIdx.x;

  constexpr int TileK = Threads * Vec;
  const int R    = K / TileK;      // number of full tiles along K
  const int main = R * TileK;      // elements covered by full tiles

  const float* arow = A + (long long)m * (long long)K;

  // CuTe views of the row of A and of B as (Vec, Threads, R) so that
  // thread `tid` owns `Vec` contiguous elements per tile.
  Tensor gA = make_tensor(make_gmem_ptr(arow),
                          make_shape(Int<Vec>{}, Int<Threads>{}, R),
                          make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}));
  Tensor gB = make_tensor(make_gmem_ptr(B),
                          make_shape(Int<Vec>{}, Int<Threads>{}, R),
                          make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}));

  Tensor tAgA = gA(_, tid, _);   // (Vec, R) : (1, TileK)
  Tensor tBgB = gB(_, tid, _);   // (Vec, R) : (1, TileK)

  float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;

  if constexpr (Vec == 4) {
    // Vectorized 128-bit loads via CuTe recast
    Tensor tAgA4 = recast<float4>(tAgA);   // (R) of float4
    Tensor tBgB4 = recast<float4>(tBgB);   // (R) of float4

    int j = 0;
    #pragma unroll 1
    for (; j + 4 <= R; j += 4) {
      float4 a0 = tAgA4(j);     float4 b0 = tBgB4(j);
      float4 a1 = tAgA4(j + 1); float4 b1 = tBgB4(j + 1);
      float4 a2 = tAgA4(j + 2); float4 b2 = tBgB4(j + 2);
      float4 a3 = tAgA4(j + 3); float4 b3 = tBgB4(j + 3);
      acc0 += a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;
      acc1 += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;
      acc2 += a2.x * b2.x + a2.y * b2.y + a2.z * b2.z + a2.w * b2.w;
      acc3 += a3.x * b3.x + a3.y * b3.y + a3.z * b3.z + a3.w * b3.w;
    }
    for (; j < R; ++j) {
      float4 a = tAgA4(j);
      float4 b = tBgB4(j);
      acc0 += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }
  } else {
    for (int j = 0; j < R; ++j) {
      CUTE_UNROLL
      for (int v = 0; v < Vec; ++v) {
        acc0 += tAgA(v, j) * tBgB(v, j);
      }
    }
  }

  float acc = acc0 + acc1 + acc2 + acc3;

  // Tail elements if K is not a multiple of Threads * Vec
  for (int e = main + tid; e < K; e += Threads) {
    acc += arow[e] * B[e];
  }

  // Block-wide reduction (warp shuffles + shared memory)
  __shared__ float smem[Threads / 32];

  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    acc += __shfl_down_sync(0xffffffffu, acc, off);
  }

  const int lane = tid & 31;
  const int warp = tid >> 5;
  if (lane == 0) smem[warp] = acc;
  __syncthreads();

  if (warp == 0) {
    constexpr int NW = Threads / 32;
    float v = (lane < NW) ? smem[lane] : 0.f;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      v += __shfl_down_sync(0xffffffffu, v, off);
    }
    if (lane == 0) C[m] = v;
  }
}

torch::Tensor matvec(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be (K, 1)");

  int64_t M = A.size(0);
  int64_t K = A.size(1);
  TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, 1}, A.options());

  constexpr int Threads = 256;

  dim3 block(Threads);
  dim3 grid((unsigned)M);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (K % 4 == 0) {
    matvec_cute_kernel<Threads, 4><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)K);
  } else {
    matvec_cute_kernel<Threads, 1><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)K);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE matvec launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=matvec_cpp_decl,
    cuda_sources=matvec_cuda_src,
    functions=["matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a single
    custom CuTe CUDA kernel (cooperative tiled reduction over K).
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
            B = B.cuda()
            return self._ext.matvec(A, B).cpu()
        if A.dtype != torch.float32:
            return torch.matmul(A, B)
        return self._ext.matvec(A, B)

